package com.formation.loan.controller;
import com.formation.loan.exception.*; import com.formation.loan.service.LoanService; import org.junit.jupiter.api.Test; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.autoconfigure.web.servlet.WebMvcTest; import org.springframework.boot.test.mock.mockito.MockBean; import org.springframework.test.web.servlet.MockMvc; import static org.mockito.Mockito.*; import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.patch; import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;
@WebMvcTest(LoanController.class) class LoanControllerTest { @Autowired MockMvc mvc; @MockBean LoanService service; @Test void doubleReturnIs409() throws Exception {when(service.returnLoan(1L)).thenThrow(new LoanException(409,"cet emprunt est déjà terminé"));mvc.perform(patch("/api/loans/1/return")).andExpect(status().isConflict());} }
